const SUB_NAMES={};NAV.forEach(n=>(n.sub||[]).forEach(([t,s])=>SUB_NAMES[s]=t));
const TOP_OF_SUB={};NAV.forEach(n=>(n.sub||[]).forEach(([t,s])=>TOP_OF_SUB[s]=n.s));
const REVIEWS=[["Jack", "Parcel received in GOOD condition. Everything is taken care of, thick bubble wrap for my items which protected it well. Recommended seller with good communication 👍🏻👍🏻👍🏻", 5, "First Partner Illustration Collection Series 1"], ["Issa", "Item arrived well packaged and quickly. A++ seller. Thank you!", 5, "Black Bolt & White Flare Unova Heavy Hitters Premium Collection"], ["Jane", "Great seller. Fast shipping. Item as described. Thank you!", 5, "Hot Wheels RLC 1965 Shelby Cobra 427 SC"], ["Mena", "A Pleasure To Buy From A+", 5, "3x 2026 $2 Anzac Dawn Service coin rolls"], ["Michael", "Very good 👍", 5, "Ascended Heroes Premium Poster Collection Gardevoir"], ["John", "Excellent seller", 5, "Ascended Heroes First Partners Deluxe Pin Collection"]];

/* ========================= STATE ========================= */
const store={get(k,d){try{const v=localStorage.getItem("joli_"+k);return v?JSON.parse(v):d}catch(e){return d}},set(k,v){try{localStorage.setItem("joli_"+k,JSON.stringify(v))}catch(e){}}};
let cart=store.get("cart",[]), wish=store.get("wish",[]), user=store.get("user",null);
const $=s=>document.querySelector(s);
const app=$("#app");
const money=n=>"$"+(Number.isInteger(n)?n.toLocaleString("en-AU"):n.toLocaleString("en-AU",{minimumFractionDigits:2,maximumFractionDigits:2}));
const esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const pct=p=>Math.round((1-p.price/p.rrp)*100);

const PRODUCT_INDEX=new Map(PRODUCTS.map(p=>[p.id,p]));const byId=id=>PRODUCT_INDEX.get(+id);

/* Placeholder art: comic starburst per product */
function artFallback(id){const p=byId(id);return artGen(p,1)}
function art(p){return p.img||artGen(p,1)}
function artGen(p,i=0){const [a,b]=CAT_COLORS[p.cat]||["#6a1fb3","#ffd21f"];const rot=(p.id*31+i*47)%360;const init=p.name.replace(/[^A-Za-z0-9 ]/g,"").split(" ").filter(Boolean).slice(0,2).map(w=>w[0].toUpperCase()).join("");const label=p.type||(p.sub&&SUB_NAMES[p.sub])||"";
 let rays="";for(let k=0;k<16;k++){const ang=k*22.5+rot;rays+=`<polygon points="200,200 ${200+260*Math.cos(ang*Math.PI/180)},${200+260*Math.sin(ang*Math.PI/180)} ${200+260*Math.cos((ang+9)*Math.PI/180)},${200+260*Math.sin((ang+9)*Math.PI/180)}" fill="${k%2?a:b}" opacity=".9"/>`}
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400"><defs><radialGradient id="g" cx="50%" cy="45%"><stop offset="0" stop-color="${i%2?a:b}"/><stop offset="1" stop-color="${i%2?b:a}"/></radialGradient></defs><rect width="400" height="400" fill="url(#g)"/>${rays}<circle cx="200" cy="200" r="118" fill="#ffffff" stroke="#141019" stroke-width="8"/><circle cx="200" cy="200" r="100" fill="${i===2?a:'#ffd21f'}" opacity=".95"/><text x="200" y="222" text-anchor="middle" font-family="Impact,Arial Black,sans-serif" font-size="78" fill="${i===2?'#fff':'#141019'}" stroke="#141019" stroke-width="2">${init}</text><rect x="70" y="300" width="260" height="44" rx="10" fill="#141019"/><text x="200" y="331" text-anchor="middle" font-family="Arial Black,Arial,sans-serif" font-weight="900" font-size="22" fill="#ffd21f">${esc(label).toUpperCase().slice(0,20)}</text></svg>`;
 return "data:image/svg+xml;charset=utf-8,"+encodeURIComponent(svg)}

/* ========================= HELPERS ========================= */
function inColl(p,slug){
 if(slug==="all")return true; if(slug==="sale")return p.price<p.rrp;
 if(slug==="sport-singles")return p.kind==="raw"&&p.cat==="sport-cards"; if(slug.endsWith("-graded"))return p.kind==="graded"&&(p.cat===slug.replace("-graded","")||(slug==="sport-graded"&&p.cat==="sport-cards"));
 if(slug==="singles")return p.kind==="graded"||p.kind==="raw";
 if(slug==="retro")return p.cat.startsWith("retro"); if(slug==="new-gaming")return p.cat.startsWith("new-");
 if(p.cat===slug)return true; return p.sub===slug;
}
function stockInfo(p){if(p.stock<=0)return{cls:"out",t:"Sold out"};if((p.kind==="used"||p.kind==="raw"||p.kind==="graded")&&p.stock===1)return{cls:"low",t:"One only"};if(p.stock<=3)return{cls:"low",t:"Only "+p.stock+" left"};return{cls:"in",t:"In stock"}}
function toast(msg){const t=document.createElement("div");t.className="toast";t.textContent=msg;document.body.appendChild(t);setTimeout(()=>t.remove(),2200)}
function cardHTML(p){const s=stockInfo(p);const inW=wish.includes(p.id);
 return `<article class="card ${p.stock<=0?'soldout':''}"><div class="tag">${p.stock>0&&p.price<p.rrp?`<span class="pill o">Save ${pct(p)}%</span>`:''}${p.stock>0&&p.tags.includes("bestseller")?'<span class="pill">Top seller</span>':''}${p.kind==="used"?'<span class="pill k">Pre-owned</span>':p.kind==="raw"?'<span class="pill p">Single · NM</span>':p.kind==="graded"?'<span class="pill g">Graded</span>':''}${p.stock<=0?'<span class="pill k">Sold out</span>':''}</div>
 <button class="wish ${inW?'on':''}" data-wish="${p.id}" aria-label="Wishlist">${inW?'♥':'♡'}</button>
 <a class="im" href="#p-${p.id}"><img src="${art(p)}" alt="" loading="lazy" data-pid="${p.id}"></a>
 <div class="body"><div class="brand">${esc(p.brand)}</div><a class="title" href="#p-${p.id}">${esc(p.name)}</a>
 <div class="price">${p.stock>0?money(p.price)+(p.price<p.rrp?`<s>${money(p.rrp)}</s>`:''):'<span class="was">Was '+money(p.price)+'</span>'}</div><div class="stock ${s.cls}">${s.t}</div>
 <div class="foot"><span class="pts"></span>${p.stock>0?`<button class="btn btn-y btn-sm" data-add="${p.id}">Add</button>`:`<button class="btn btn-sm" data-notify="${p.id}">Notify me</button>`}</div></div></article>`}
function gridHTML(list){return `<div class="grid">${list.map(cardHTML).join("")}</div>`}

/* ========================= CART ========================= */
function cartKey(id){return id+"::"}
function addToCart(id,qty=1){const p=byId(id);if(!p)return;
 const k=cartKey(id);const it=cart.find(i=>i.k===k);if(it)it.qty+=qty;else cart.push({k,id,qty});store.set("cart",cart);renderCounts();toast("Added: "+p.name);openDrawer()}
function setQty(k,q){const it=cart.find(i=>i.k===k);if(!it)return;it.qty=Math.max(0,q);if(it.qty===0)cart=cart.filter(i=>i.k!==k);store.set("cart",cart);renderCounts();refreshCartViews()}
function subtotal(){return cart.reduce((s,i)=>s+byId(i.id).price*i.qty,0)}
function renderCounts(){const n=cart.reduce((s,i)=>s+i.qty,0);const c=$("#cartCount");c.textContent=n;c.hidden=!n;const w=$("#wishCount");w.textContent=wish.length;w.hidden=!wish.length;$("#acctLbl").textContent=user?user.name.split(" ")[0]:"Account"}
function cartItemHTML(i,full){const p=byId(i.id);return `<div class="citem"><img src="${art(p)}" alt="" loading="lazy" decoding="async" width="640" height="640" data-pid="${p.id}"><div class="t"><a href="#p-${p.id}" style="text-decoration:none;color:inherit">${esc(p.name)}</a><small>${money(p.price)} each</small>${full?'':`<div class="qty" style="margin-top:6px"><button data-q="${i.k}" data-d="-1">−</button><input value="${i.qty}" data-qin="${i.k}" inputmode="numeric" aria-label="Quantity"><button data-q="${i.k}" data-d="1">+</button></div>`}</div>${full?`<div class="qty"><button data-q="${i.k}" data-d="-1">−</button><input value="${i.qty}" data-qin="${i.k}" inputmode="numeric" aria-label="Quantity"><button data-q="${i.k}" data-d="1">+</button></div>`:''}<div style="text-align:right;font-weight:900">${money(p.price*i.qty)}<br><button class="rm" data-rm="${i.k}">Remove</button></div></div>`}
let drawerOpen=false;
function openDrawer(){drawerOpen=true;renderDrawer()}
function closeDrawer(){drawerOpen=false;$("#overlay").innerHTML=""}
function renderDrawer(){if(!drawerOpen)return;$("#overlay").innerHTML=`<div class="drawer-bg" data-close></div><aside class="drawer" aria-label="Cart"><div class="dh"><h3>Your Cart (${cart.reduce((s,i)=>s+i.qty,0)})</h3><button class="btn btn-sm" data-close>Close</button></div><div class="items">${cart.length?cart.map(i=>cartItemHTML(i,false)).join(""):'<div class="empty">Cart is empty. Go fill it with loot.</div>'}</div><div class="df"><div class="sub"><span>Subtotal</span><span>${money(subtotal())}</span></div><div style="font-weight:700;color:var(--muted);font-size:13px">${subtotal()>=150?'🎉 Free shipping unlocked':'Add '+money(150-subtotal())+' more for free shipping'}</div><a class="btn btn-p" href="#cart" data-close>View cart</a><a class="btn btn-y" href="#checkout" data-close>Checkout</a></div></aside>`}
function refreshCartViews(){renderDrawer();if(route().page==="cart")render()}
function toggleWish(id){id=+id;if(wish.includes(id))wish=wish.filter(x=>x!==id);else{wish.push(id);toast("Saved to wishlist")}store.set("wish",wish);renderCounts();document.querySelectorAll(`[data-wish="${id}"]`).forEach(b=>{const on=wish.includes(id);b.classList.toggle("on",on);b.textContent=on?"♥":"♡"});if(route().page==="wishlist")render()}

/* ========================= ROUTER ========================= */
let searchQuery="";let collState={};
const PATH_MODE=/(^|\.)jolimania\.com$/.test(location.hostname);
function hashToPath(hash){const h=(hash||"").replace(/^#/,"");if(!h||h==="home")return"/";if(h.startsWith("c-"))return"/shop/"+h.slice(2);if(h.startsWith("p-"))return"/product/"+h.slice(2);if(h==="s")return"/search";return"/"+h}
function pathToHash(path){const p=path.replace(/\/+$/,"")||"/";if(p==="/")return"home";let m;if((m=p.match(/^\/shop\/([\w-]+)$/)))return"c-"+m[1];if((m=p.match(/^\/product\/(\d+)$/)))return"p-"+m[1];if(p==="/search")return"s";return p.slice(1)}
function routeHash(){if(PATH_MODE&&!location.hash)return pathToHash(location.pathname);return(location.hash||"#home").slice(1)}
function route(){const h=routeHash();const i=h.indexOf("-");const page=i>0?h.slice(0,i):h;const param=i>0?h.slice(i+1):"";return{page,param}}
function navigate(hash){if(PATH_MODE){history.pushState(null,"",hashToPath(hash));onNav()}else location.hash=hash}
function onNav(){closeDrawer();$("#mobileNav").hidden=true;render();markNav();window.scrollTo({top:0});if(document.activeElement&&document.activeElement.closest("nav.main"))document.activeElement.blur()}
function markNav(){const r=route();let cur=null;if(r.page==="c"){cur=TOP_OF_SUB[r.param]||r.param;if(cur==="retro-consoles"||cur==="retro-games")cur="retro"}else if(r.page==="p"){const p=byId(+r.param);if(p)cur=p.cat.startsWith("retro")?"retro":p.cat}document.querySelectorAll("nav.main a.top").forEach(a=>a.classList.toggle("active",a.dataset.nav===cur))}
window.addEventListener("hashchange",onNav);
if(PATH_MODE){window.addEventListener("popstate",onNav);
 if(location.hash){history.replaceState(null,"",hashToPath(location.hash))}
 document.addEventListener("click",e=>{const a=e.target.closest("a[href]");if(!a||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||a.target==="_blank")return;const href=a.getAttribute("href");if(href.startsWith("#")){e.preventDefault();navigate(href);return}if(href.startsWith("/")&&!href.startsWith("//")){e.preventDefault();history.pushState(null,"",href);onNav()}});}
document.querySelector("nav.main").addEventListener("click",e=>{const a=e.target.closest("a");if(a){a.blur();document.querySelectorAll("nav.main .mega").forEach(m=>{m.style.display="none";setTimeout(()=>m.style.display="",250)})}});

function render(){const r=route();if(!PATH_MODE&&(r.page==="home"||r.page==="")&&location.hash)history.replaceState(null,"",location.pathname+location.search);document.querySelectorAll(".modal").forEach(m=>m.remove());
 switch(r.page){case"home":case"":app.innerHTML=homeHTML();startHero();break;case"c":app.innerHTML=collectionHTML(r.param);break;case"p":app.innerHTML=productHTML(+r.param);break;case"s":app.innerHTML=searchHTML();break;case"cart":app.innerHTML=cartPageHTML();break;case"checkout":app.innerHTML=checkoutHTML();break;case"about":app.innerHTML=aboutHTML();break;case"stores":app.innerHTML=storesHTML();break;case"account":app.innerHTML=accountHTML();break;case"wishlist":app.innerHTML=wishlistHTML();break;case"shipping":app.innerHTML=shippingHTML();break;case"faq":app.innerHTML=faqHTML();break;case"privacy":app.innerHTML=privacyHTML();break;case"returns":app.innerHTML=returnsHTML();break;case"terms":app.innerHTML=termsHTML();break;default:app.innerHTML=`<div class="empty" style="margin-top:30px">That page rolled a natural 1. <a href="#home">Head home</a>.</div>`}
 if(PATH_MODE)document.querySelectorAll('a[href^="#"]').forEach(a=>{a.setAttribute("href",hashToPath(a.getAttribute("href")))});
 const toc=app.querySelector(".toc");if(toc){const hs=[...app.querySelectorAll(".prose h2")];if(hs.length<3)toc.remove();else{toc.innerHTML="<b>On this page</b>"+hs.map((x,i)=>{x.id="sec-"+i;return `<button type="button" class="linkish" data-sec="${x.id}">${x.textContent.replace(/^\d+\.\s*/,"")}</button>`}).join("")}}}

